    def __init__(self, tree, path=()):
        self.tree = tree
        self.path = tuple(path)

    @staticmethod
    def from_tree(tree):
        return Zipper(tree)

    def value(self):
        return self.tree["value"]

    def set_value(self, value):
        return Zipper({**self.tree, "value": value}, self.path)

    def left(self):
        sub = self.tree["left"]
        if sub is None:
            return None
        return Zipper(sub, self.path + (("left", self.tree),))

    def set_left(self, tree):
        return Zipper({**self.tree, "left": tree}, self.path)

    def right(self):
        sub = self.tree["right"]
        if sub is None:
            return None
        return Zipper(sub, self.path + (("right", self.tree),))

    def set_right(self, tree):
        return Zipper({**self.tree, "right": tree}, self.path)

    def up(self):
        if not self.path:
            return None
        side, parent = self.path[-1]
        return Zipper({**parent, side: self.tree}, self.path[:-1])

    def to_tree(self):
        z = self
        while z.path:
            z = z.up()
        return z.tree
